-- =============================================================================
-- seed.sql
-- Seed data for Temperies Mundial
-- Source of truth: server/prisma/seed.js (29 users + 72 World Cup 2026 matches)
-- No predictions — those are user-generated at runtime.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Users (1 admin + 28 employees)
-- Passwords are stored in plain text to match the existing Express backend.
-- IDs are generated by Supabase (gen_random_uuid()).
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Matches (72 World Cup 2026 group stage matches)
-- Generated by the same deterministic algorithm as server/prisma/seed.js.
-- IDs are TEXT PKs in "M01"–"M72" format (not sequential by match number —
-- they are sorted by date, so M01 is the earliest match chronologically).
-- home_team / away_team store the 2-letter country code (e.g. 'mx', 'ar').
-- ---------------------------------------------------------------------------

